// smoke: the pilots' calls for orders (cards space-game-order-calls, one-list-keys and list-shortcuts; src/camporders.js, src/camporderdraw.js, content/text/camporders.md), plain Node, no Chrome
// A pilot radios what he sees and asks for orders: three timed choices in a small amber list (Up, Down, Enter), an answer that is a real order or a real cost in the sim, the cautious pick when nobody answers.
//   A. the table: six call types of three choices each, every effect there, the words (fixed lines, short, no alien or pirate named: the calls are on every level)
//   B. each trigger, on a state built by hand: wounded, cruiser, breakaway, second, running, opportunity
//   C. the clock: not before 40 s of the mission, one call in 25 s, the same type not again in 70 s, 8 s to answer, the slowed battle counts the player's seconds, a ship that is gone closes the call
//   D. each effect: what the sim does for a choice, and the cautious pick when a choice cannot be done
//   E. the same flight makes the same calls; the bots still win (a plain one that answers at once, one that thinks), the idle one never answers
//   F. the prompt (a stand-in scene): the plate and its rows; the call is a LIST: the highlight starts on the pilot's own pick, Up and Down move it (round at the ends), Enter answers with it, Left and Right are swallowed,
//      a digit answers nothing; the call does not take a key while an order list (Q or P, or a part's: W E R, O I U, the stance) or the map is open (the plate dims and says so) or the battle is not on; campCallHasKeys (the ship coasts while it is true); the radio's lines
//   G. what an answer is worth
//   H. the hold (card space-game-call-timer-stops): touch the prompt (Up or Down) and the 8 s stop; it waits for Enter, 30 s at the most; untouched it runs out as ever; no other key holds it
// Run: node tests/camporders.mjs   (exit code 1 on a failed check)
import { readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { nodeGame } from './nodegame.mjs';
import { run as botRun, techsFor, botGame } from '../tools/campaign-bot.mjs';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
let failed = 0;
const check = (name, cond, detail = '') => { if (cond) console.log('  ok   ' + name); else { failed++; console.log(`  FAIL ${name}${detail ? '  (' + String(detail).slice(0, 400) + ')' : ''}`); } };
const g = nodeGame();
const J = e => JSON.parse(g.run(`JSON.stringify(${e}) ?? 'null'`));
// a battle with nothing in it but the cruiser, as if 60 s of the mission had gone: a level's waves and convoys marked as started so that nothing else arrives
g.run(`window.__box = (lv, mi) => { const C = campNew(lv, [], { seed: 1, mission: mi || 0 }); C.arrivedAt = 0; C.t = 60000; C.ships = C.ships.filter(u => u.kind === 'carrier'); C.by = { [C.carrier.id]: C.carrier }; C.waves.forEach(w => { w.started = true; }); C.convoys.forEach(c => { c.started = true; }); return C; };
window.__put = (C, kind, x, y, extra) => { const u = campSpawn(C, kind, x, y); if (u.team === 'earth' && !u.order) u.order = { type: 'guard', at: { kind: 'carrier' } }; Object.assign(u, extra || {}); return u; }; // a ship of ours launched into the battle guards the cruiser
window.__tick = (C, n) => { for (let i = 0; i < (n || 1); i++) campCallsTick(C, 1 / 30); };`);
const text = f => readFileSync(join(ROOT, f), 'utf8');

// ---- A. the table ----
const MINE = /\.(distress|rescue|rescueall|stay)$/; // the scripted distress call of mission 1.1 (src/campbeats.js)
const types = J('CAMP_CALL_TYPES.filter(t => !t.scripted).map(t => ({ id: t.id, pick: t.pick, def: t.def }))'); // (a call a mission scripts itself, with scripted: true, is not one of the six that watch the fight: src/campbeats.js)
const fxIds = J('Object.keys(CAMP_CALL_FX)').filter(f => !/^(rescue|rescueall|stay)$/.test(f)); // (the effects of 1.1's scripted call are not the ones that watch the fight)
check('six call types, each with three choices, every choice an effect of the table, and a cautious pick among them', types.length === 6 && types.every(t => t.pick.length === 3 && t.pick.every(p => fxIds.includes(p)) && t.def >= 0 && t.def <= 2 && new Set(t.pick).size === 3), JSON.stringify(types));
check('the types are the five of the card (a breakaway at the escort, a wounded wingman, the enemy running, a second group sighted, a target of opportunity) and the cruiser\'s shield', ['breakaway', 'wounded', 'running', 'second', 'opportunity', 'cruiser'].every(id => types.some(t => t.id === id)));
const words = id => J(`uiText('${id}')`);
const spoken = [].concat(types.map(t => 'camp.call.line.' + t.id), fxIds.map(f => 'camp.call.r.' + f), ['camp.call.late', 'camp.call.fail']);
check('every call, choice and answer has its words (a key with no text reads as its own name): ' + spoken.length + ' spoken lines and ' + fxIds.length + ' labels', spoken.every(k => words(k) !== k) && fxIds.every(f => words('camp.call.fx.' + f) !== 'camp.call.fx.' + f));
check('the spoken lines are curt (12 words at most), fixed (no placeholder: the voice pack records each once) and name no alien and no pirate (the calls are on every level)', spoken.every(k => { const t = words(k); return t.split(/\s+/).length <= 12 && !/[{}]/.test(t) && !/alien|pirate|raider|mothership/i.test(t); }), spoken.filter(k => !/^[^{}]*$/.test(words(k)) || words(k).split(/\s+/).length > 12).join());
check('the labels on the prompt are short (24 characters at most) and every type has an effect for each of its three rows', fxIds.every(f => words('camp.call.fx.' + f).length <= 24));
check('the voice pack says the calls and their answers are said (in the pilots\' voices) and the labels and the plate\'s three lines (the "if you wait" mark, the keys line, the "timer stopped" line and "close the list" while a list has the keys) are only shown: 0 unclassified', (() => { const k = J('voicePackKeys()'); return k.unclassified.length === 0 && (k.spoken['campaign.chatter'] || { keys: [] }).keys.filter(x => /^camp\.call\./.test(x) && !MINE.test(x)).length === spoken.length && k.silent.filter(x => /^camp\.call\./.test(x.key) && !MINE.test(x.key)).map(x => x.key).sort().join() === fxIds.map(f => 'camp.call.fx.' + f).concat(['camp.call.hud.def', 'camp.call.hud.held', 'camp.call.hud.keys', 'camp.call.hud.wait']).sort().join(); })()); // (MINE: the scripted call of mission 1.1, src/campbeats.js, has words of its own)

// ---- B. the triggers ----
const open = e => J(`(() => { const C = ${e}; __tick(C); return C.call.open ? { id: C.call.open.id, ctx: C.call.open.ctx } : null; })()`);
check('WOUNDED: a fighter at 30 percent of his hull with an enemy 200 px off calls (his id and the enemy\'s); at full hull he does not; with no enemy near he does not',
  (() => { const a = open(`(() => { const C = __box(2, 1), c = C.carrier, f = __put(C, 'fighter', c.x + 300, c.y); f.hp = f.maxHp * 0.3; __put(C, 'raider', c.x + 500, c.y); return C; })()`);
    const b = open(`(() => { const C = __box(2, 1), c = C.carrier; __put(C, 'fighter', c.x + 300, c.y); __put(C, 'raider', c.x + 500, c.y); return C; })()`);
    const d = open(`(() => { const C = __box(2, 1), c = C.carrier, f = __put(C, 'fighter', c.x + 300, c.y); f.hp = f.maxHp * 0.3; __put(C, 'raider', c.x + 3000, c.y); return C; })()`);
    return a && a.id === 'wounded' && /^fighter-/.test(a.ctx.who) && a.ctx.ids.length === 1 && b === null && d === null; })());
check('CRUISER: the shield at 30 percent with an enemy within 900 px calls; with the shield whole, or the enemy far, it does not',
  open(`(() => { const C = __box(2, 1), c = C.carrier; C.shield = 40; __put(C, 'raider', c.x + 600, c.y); return C; })()`)?.id === 'cruiser'
  && open(`(() => { const C = __box(2, 1), c = C.carrier; __put(C, 'raider', c.x + 600, c.y); return C; })()`) === null && open(`(() => { const C = __box(2, 1), c = C.carrier; C.shield = 40; __put(C, 'raider', c.x + 2000, c.y); return C; })()`) === null);
check('BREAKAWAY: an enemy beside a convoy ship the cruiser is 2,000 px from, with none of the wing near her, calls; two enemies call even with an escort beside her; the cruiser close by (900 px) takes it itself',
  (() => { const mk = (extra) => `(() => { const C = __box(1, 0), c = C.carrier, f = __put(C, 'freighter', c.x + 2000, c.y); f.dest = { x: f.x + 9000, y: f.y }; ${extra}; return C; })()`;
    const a = open(mk(`__put(C, 'skiff', f.x + 300, f.y)`)), b = open(mk(`__put(C, 'skiff', f.x + 300, f.y); __put(C, 'escort', f.x + 100, f.y)`)), d = open(mk(`__put(C, 'skiff', f.x + 300, f.y); __put(C, 'skiff', f.x + 350, f.y + 40); __put(C, 'escort', f.x + 100, f.y)`));
    const e = open(`(() => { const C = __box(1, 0), c = C.carrier, f = __put(C, 'freighter', c.x + 600, c.y); f.dest = { x: f.x + 9000, y: f.y }; __put(C, 'skiff', f.x + 300, f.y); return C; })()`);
    return a && a.id === 'breakaway' && /^freighter-/.test(a.ctx.who) && b === null && d && d.id === 'breakaway' && d.ctx.ids.length === 2 && e === null; })());
check('SECOND: two ships of a wave that came in the last 9 s with the first group still within 2,500 px call; a wave that came 20 s ago, or a lone first arrival (no group about), does not',
  (() => { const mk = (age, first) => `(() => { const C = __box(2, 1), c = C.carrier; C.waves.length = 0; C.waves.push({ started: true }, { started: true }); C.call = { n: 0, next: 0, open: null, last: {}, seen: { 0: C.t - 40000, 1: C.t - ${age} }, log: [] };
      ${first ? "__put(C, 'raider', c.x + 900, c.y, { wave: 0 });" : ''} const a = __put(C, 'raider', c.x + 1800, c.y + 100, { wave: 1 }), b = __put(C, 'drone', c.x + 1850, c.y - 100, { wave: 1 }); return C; })()`;
    return open(mk(3000, true))?.id === 'second' && open(mk(20000, true)) === null && open(mk(3000, false)) === null; })());
check('RUNNING: a pirate that has broken off and is running within 1,600 px calls; one that is far, or fighting, does not',
  open(`(() => { const C = __box(1, 0), c = C.carrier, u = __put(C, 'skiff', c.x + 900, c.y); u.running = { since: C.t, why: 'hurt' }; return C; })()`)?.id === 'running'
  && open(`(() => { const C = __box(1, 0), c = C.carrier, u = __put(C, 'skiff', c.x + 5000, c.y); u.running = { since: C.t, why: 'hurt' }; return C; })()`) === null && open(`(() => { const C = __box(1, 0), c = C.carrier; __put(C, 'skiff', c.x + 900, c.y); return C; })()`) === null);
check('OPPORTUNITY: a gunship alone (nothing within 700 px of it) in missile reach with a missile in the tube calls; with another enemy beside it, or with no missile, it does not',
  open(`(() => { const C = __box(2, 1), c = C.carrier; __put(C, 'gunship', c.x + 1500, c.y); return C; })()`)?.id === 'opportunity'
  && open(`(() => { const C = __box(2, 1), c = C.carrier; __put(C, 'gunship', c.x + 1500, c.y); __put(C, 'drone', c.x + 1700, c.y); return C; })()`) === null && open(`(() => { const C = __box(2, 1), c = C.carrier; C.missiles = 0; __put(C, 'gunship', c.x + 1500, c.y); return C; })()`) === null);

// ---- C. the clock ----
check('no call in the first 40 s of the mission, though a wingman is burning (the first minute\'s hints come first), and none before the cruiser has reached the place of the mission',
  (() => { const r = J(`(() => { const C = __box(2, 1), c = C.carrier; C.t = 30000; const f = __put(C, 'fighter', c.x + 300, c.y); f.hp = 5; __put(C, 'raider', c.x + 500, c.y); __tick(C); const early = !!C.call.open; C.t = 41000; __tick(C); const later = !!C.call.open; const D = __box(2, 1); D.arrivedAt = null; const f2 = __put(D, 'fighter', D.carrier.x + 300, D.carrier.y); f2.hp = 5; __put(D, 'raider', D.carrier.x + 500, D.carrier.y); __tick(D); return [early, later, !!D.call.open]; })()`); return r[0] === false && r[1] === true && r[2] === false; })());
check('the pilot waits 8 s; with no answer he takes the cautious pick himself and says so (a late answer), and the prompt is gone',
  (() => { const r = J(`(() => { const C = __box(2, 1), c = C.carrier, f = __put(C, 'fighter', c.x + 300, c.y); f.hp = f.maxHp * 0.3; __put(C, 'raider', c.x + 500, c.y); __tick(C); const l0 = C.call.open.left; __tick(C, 30 * 4); const l1 = C.call.open.left; __tick(C, 30 * 4 + 2); const ev = C.events.filter(e => e.type === 'call').map(e => e.stage + ':' + (e.how || '') + ':' + (e.pick || '')); return [l0, l1, !!C.call.open, ev, f.order && f.order.type]; })()`); return Math.abs(r[0] - 8) < 0.05 && Math.abs(r[1] - 4) < 0.15 && r[2] === false && r[3].join() === 'open::,answer:late:home' && r[4] === 'recall'; })());
check('the pilot\'s clock is the battle\'s own (no command time: card space-game-no-command-slowdown): 2 s of ticks take 2 s off the 8, even if something set a C.timeScale, which nothing reads',
  (() => { const r = J(`(() => { const C = __box(2, 1), c = C.carrier, f = __put(C, 'fighter', c.x + 300, c.y); f.hp = f.maxHp * 0.3; __put(C, 'raider', c.x + 500, c.y); __tick(C); C.timeScale = 0.25; for (let i = 0; i < 30 * 2; i++) campCallsTick(C, 1 / 30); return [C.call.open.left]; })()`); return Math.abs(r[0] - 6) < 0.1; })());
check('one call in 25 s at most, and the same type not again inside 70 s, however many are burning: calls come at 25 s and the next type waits for its turn',
  (() => { const r = J(`(() => { const C = __box(2, 1), c = C.carrier; const f = __put(C, 'fighter', c.x + 300, c.y); f.hp = 5; f.maxHp = 400; __put(C, 'raider', c.x + 500, c.y); C.shield = 30; const at = []; for (let i = 0; i < 30 * 100; i++) { C.t += 1000 / 30; campCallsTick(C, 1 / 30); if (C.call.open) { at.push([Math.round(C.t / 1000), C.call.open.id]); campCallAnswer(C, 2, 'key'); } f.hp = 5; if (!C.by[f.id]) break; f.order = null; if (C.by[f.id] && f.order == null) f.order = { type: 'guard', at: { kind: 'carrier' } }; } return at; })()`);
    const gaps = r.slice(1).map((x, i) => x[0] - r[i][0]); return r.length >= 3 && gaps.every(x => x >= 25) && r.filter(x => x[1] === 'wounded').length <= 2 && r.filter(x => x[1] === 'wounded').every((x, i, a) => !i || x[0] - a[i - 1][0] >= 70); })());
check('a call about a ship that is gone is closed with no order given (the wounded wingman dies while the prompt waits)',
  (() => { const r = J(`(() => { const C = __box(2, 1), c = C.carrier, f = __put(C, 'fighter', c.x + 300, c.y); f.hp = f.maxHp * 0.3; const e = __put(C, 'raider', c.x + 500, c.y); __tick(C); const was = !!C.call.open; f.hp = 0; e.hp = 0; C.events.length = 0; __tick(C); return [was, !!C.call.open, C.events.map(x => x.type + ':' + x.stage)]; })()`); return r[0] && !r[1] && r[2].join() === 'call:gone'; })());

// ---- D. the effects ----
const answer = (setup, n, after) => J(`(() => { const C = __box(${setup.lv || 2}, ${setup.mi == null ? 1 : setup.mi}), c = C.carrier; const X = {}; ${setup.js}; __tick(C); X.id = C.call.open && C.call.open.id; C.events.length = 0; X.res = campCallAnswer(C, ${n}, 'key'); X.ev = C.events.filter(e => e.type === 'call').map(e => e.how + ':' + e.pick); ${after || ''}; return X; })()`);
const wnd = { js: "const f = __put(C, 'fighter', c.x + 300, c.y), e = __put(C, 'raider', c.x + 500, c.y), h = __put(C, 'fighter', c.x - 200, c.y); f.hp = f.maxHp * 0.3; X.f = f.id; X.e = e.id; X.h = h.id; C.carrier.x = 0" };
check('WOUNDED 1 Cover him: the whole wing guards the wounded ship (their orders are guard, at him)', (() => { const r = answer(wnd, 1, "X.o = C.ships.filter(u => u.kind === 'fighter').map(u => u.order && u.order.type + ':' + (u.order.at && u.order.at.id))"); return r.res.pick === 'cover' && r.o.every(o => o === 'guard:' + r.f); })());
check('WOUNDED 2 Bring him home: he alone is ordered to recall (and the rest are not), and he lands when he reaches the cruiser', (() => { const r = answer(wnd, 2, "X.o = C.ships.filter(u => u.kind === 'fighter').map(u => u.id + '=' + (u.order && u.order.type)); C.by[X.f].x = c.x + 10; C.by[X.f].y = c.y; C.ships.forEach(u => { if (u.id === X.f) campAI(C, u, 1 / 30); }); X.bay = C.bay.fighters; X.alive = C.by[X.f] && C.by[X.f].hp > 0"); return r.res.pick === 'home' && r.o.filter(x => /recall/.test(x)).length === 1 && r.o.some(x => x.startsWith(r.f + '=recall')) && r.alive === false; })());
check('WOUNDED 3 Keep fighting: nothing is ordered', (() => { const r = answer(wnd, 3, "X.o = C.ships.filter(u => u.kind === 'fighter').map(u => u.order && u.order.type).join()"); return r.res.pick === 'fight' && !/recall|guard:/.test(String(r.o).replace(/guard(?=,|$)/g, '')) ; })());
const brk = (n) => answer({ lv: 1, mi: 0, js: "const fr = __put(C, 'freighter', c.x + 2000, c.y); fr.dest = { x: fr.x + 9000, y: fr.y }; const a = __put(C, 'skiff', fr.x + 300, fr.y, { goal: 'convoy:h1', prey: 'haulers' }), b = __put(C, 'skiff', fr.x + 350, fr.y + 60, { goal: 'convoy:h1' }); const fi = __put(C, 'fighter', c.x + 100, c.y), es = __put(C, 'escort', c.x + 120, c.y); X.a = a.id; X.fi = fi.id; X.es = es.id" }, n, "X.fo = C.by[X.fi].order; X.eo = C.by[X.es].order; X.ga = C.by[X.a].goal; X.pr = C.by[X.a].prey; X.hb = C.by[X.a].hitBy === C.carrier.id; X.d = C.by[X.a].distractedUntil > C.t");
check('BREAKAWAY 1 Fighters intercept: the fighters attack the nearest of them (the escorts keep their orders)', (() => { const r = brk(1); return r.res.pick === 'intercept' && r.fo.type === 'attack' && r.fo.target === r.a && r.eo.type !== 'attack'; })());
check('BREAKAWAY 2 Hold formation: nothing is ordered; BREAKAWAY 3 Leave them to the cruiser: they drop their goal, hunt the carrier and are on it for 8 s (a pirate that was set on the convoy is on the cruiser now)', (() => { const h = brk(2), d = brk(3); return h.res.pick === 'hold' && h.fo.type !== 'attack' && h.ga === 'convoy:h1' && d.res.pick === 'draw' && d.ga === '' && d.pr === 'carrier' && d.hb && d.d; })());
check('the pirate AI really does turn on the cruiser after "leave them to the cruiser" (its goal was the hauler; a few seconds on, its target is the carrier)', (() => { const r = J(`(() => { const C = __box(1, 0), c = C.carrier, fr = __put(C, 'freighter', c.x + 2000, c.y); fr.dest = { x: fr.x + 9000, y: fr.y }; fr.id = 'freighter-h1'; C.by[fr.id] = fr; const a = __put(C, 'skiff', fr.x + 300, fr.y, { goal: 'convoy:h1', prey: 'haulers' }); const before = campPirateTarget(C, a).id; __tick(C); C.call.open = { id: 'breakaway', ctx: { who: fr.id, ids: [a.id] }, pilot: 0, left: 8, total: 8, def: 1 }; campCallAnswer(C, 3, 'key'); return [before, campPirateTarget(C, a).id, c.id]; })()`); return r[0] === 'freighter-h1' && r[1] === r[2]; })());
const sec = (n) => answer({ js: "C.waves.length = 0; C.waves.push({ started: true }, { started: true }); C.call = { n: 0, next: 0, open: null, last: {}, seen: { 0: C.t - 40000, 1: C.t - 3000 }, log: [] }; __put(C, 'raider', c.x + 900, c.y, { wave: 0 }); const a = __put(C, 'raider', c.x + 1800, c.y + 100, { wave: 1 }); __put(C, 'drone', c.x + 1850, c.y - 100, { wave: 1 }); const fi = __put(C, 'fighter', c.x + 100, c.y), es = __put(C, 'escort', c.x + 120, c.y); X.a = a.id; X.fi = fi.id; X.es = es.id" }, n, "X.fo = C.by[X.fi].order; X.eo = C.by[X.es].order");
check('SECOND: 1 Fighters intercept (fighters only attack the nearest of the new group), 3 All ships attack (the escorts too), 2 Hold formation (nothing)', (() => { const a = sec(1), b = sec(3), d = sec(2); return a.id === 'second' && a.fo.type === 'attack' && a.eo.type !== 'attack' && b.fo.type === 'attack' && b.eo.type === 'attack' && d.fo.type !== 'attack' && d.eo.type !== 'attack'; })());
const run1 = (n, extra) => answer({ js: "const u = __put(C, 'skiff', c.x + 900, c.y); u.running = { since: C.t, why: 'hurt' }; const fi = __put(C, 'fighter', c.x + 100, c.y); X.u = u.id; X.fi = fi.id; " + (extra || '') }, n, "X.fo = C.by[X.fi].order; X.m = C.missiles; X.rk = C.rockets.length");
check('RUNNING: 1 Fighters give chase (they attack the runner), 2 Let them go (nothing), 3 Fire a missile (one less in the magazine, a rocket at the runner)', (() => { const a = run1(1), b = run1(2), d = run1(3); return a.res.pick === 'chase' && a.fo.type === 'attack' && a.fo.target === a.u && b.res.pick === 'letgo' && b.fo.type !== 'attack' && d.res.pick === 'missile' && d.m === J('CAMP.missile.magazine') - 1 && d.rk === 1; })());
check('a choice that cannot be done is not: with the magazine empty "Fire a missile" is not fired, the cautious pick (Let them go) is, and the pilot says he cannot (how: fail)', (() => { const r = run1(3, 'C.missiles = 0;'); return r.res.how === 'fail' && r.res.pick === 'letgo' && r.rk === 0 && r.m === 0 && r.ev.join() === 'fail:letgo'; })());
const opp = n => answer({ js: "const u = __put(C, 'gunship', c.x + 1500, c.y); const fi = __put(C, 'fighter', c.x + 100, c.y); X.u = u.id; X.fi = fi.id" }, n, "X.fo = C.by[X.fi].order; X.m = C.missiles; X.rk = C.rockets.length");
check('OPPORTUNITY: 1 Fire a missile (at the gunship), 2 Fighters strike it, 3 Leave it (nothing, and it is the cautious pick)', (() => { const a = opp(1), b = opp(2), d = opp(3); return a.res.pick === 'missile' && a.rk === 1 && a.m === J('CAMP.missile.magazine') - 1 && b.res.pick === 'strike' && b.fo.type === 'attack' && b.fo.target === b.u && d.res.how === 'key' && d.res.pick === 'leave' && d.rk === 0 && d.fo.type !== 'attack'; })());
